const A='/api/v1/admin-web';
const S={token:localStorage.getItem('nexus_admin_token')||'',portal:sessionStorage.getItem('nexus_portal_token')||'',page:'dashboard',me:null};
const $=s=>document.querySelector(s);const app=$('#app');
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function toast(t){const d=document.createElement('div');d.className='toast';d.textContent=t;document.body.appendChild(d);setTimeout(()=>d.remove(),2600)}
async function req(path,opt={},portal=false){const h=new Headers(opt.headers||{});h.set('Content-Type','application/json');const tok=portal?S.portal:S.token;if(tok)h.set('Authorization','Bearer '+tok);const r=await fetch(A+path,{...opt,headers:h});let data=null;try{data=await r.json()}catch{}if(!r.ok)throw new Error(data?.detail||('HTTP '+r.status));return data}
function badge(v){const s=String(v??'—').toUpperCase();const c=s.includes('ACTIVE')||s.includes('ON')||s==='TRUE'?'ok':s.includes('OFF')||s.includes('BLOCK')?'bad':'';return `<span class="badge ${c}">${esc(s)}</span>`}
function login(){app.innerHTML=`<div class="login"><section class="card"><div class="brand"><div class="mark">N</div><div><h1>NEXUS Control Center</h1><small>Admin Web / User Portal</small></div></div><form id="login"><label>نام کاربری<input name="username" autocomplete="username" required></label><label>رمز عبور<input type="password" name="password" autocomplete="current-password" required></label><button class="primary" type="submit">ورود مدیر</button></form><hr style="border-color:#243241"><button id="portal" class="ghost">ورود کاربر به Portal</button></section></div>`;$('#login').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const x=await req('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});S.token=x.token;localStorage.setItem('nexus_admin_token',x.token);S.me=x.user;render();}catch(err){toast(err.message)}};$('#portal').onclick=portalLogin}
function portalLogin(){app.innerHTML=`<div class="login"><section class="card portal"><h2>ورود کاربر</h2><p class="muted">برای مشاهده حساب، دسترسی‌ها و وضعیت MT5.</p><form id="pl"><label>Telegram ID<input name="telegram_id" inputmode="numeric" required></label><label>License Key<input name="license_key" required></label><div class="actions"><button type="button" id="back" class="ghost">بازگشت</button><button class="primary">ورود</button></div></form></section></div>`;$('#back').onclick=()=>S.token?render():login();$('#pl').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const b=Object.fromEntries(f);b.telegram_id=+b.telegram_id;try{const x=await req('/portal/auth/login',{method:'POST',body:JSON.stringify(b)});S.portal=x.token;sessionStorage.setItem('nexus_portal_token',x.token);await portalView()}catch(err){toast(err.message)}}}
async function portalView(){try{const d=await req('/portal/overview',{},true);app.innerHTML=`<div class="shell"><div class="top"><div class="brand"><div class="mark">N</div><div><h1>پرتال کاربر</h1><small>${esc(d.user.first_name||d.user.username||d.user.telegram_id)}</small></div></div><button id="exit" class="ghost">خروج</button></div><div class="grid"><section class="card metric"><b>${d.entitlements.vip?'فعال':'قفل'}</b><span>VIP</span></section><section class="card metric"><b>${d.entitlements.autotrade?'فعال':'قفل'}</b><span>AutoTrade</span></section><section class="card metric"><b>${esc(d.mt5?.account_number||'—')}</b><span>MT5</span></section><section class="card metric"><b>${esc(d.user.points_balance)}</b><span>امتیاز</span></section></div><section class="card"><h3>مدیریت ریسک</h3><div class="row"><span>حد زیان روزانه</span><b>${esc(d.risk.daily_loss_limit_r)}R</b></div><div class="row"><span>Dynamic Risk</span>${badge(!!d.risk.dynamic_risk_enabled)}</div><div class="row"><span>Kill Switch</span>${badge(!!d.risk.kill_switch)}</div></section><section class="card"><h3>معاملات زنده</h3>${d.live.length?d.live.map(x=>`<div class="row"><div><b>${esc(x.symbol)}</b><div class="muted">#${esc(x.ticket)}</div></div>${badge(x.status)}</div>`).join(''):'<p class="muted">معامله زنده‌ای وجود ندارد.</p>'}</section></div>`;$('#exit').onclick=()=>{S.portal='';sessionStorage.removeItem('nexus_portal_token');S.token?render():login()}}catch(e){S.portal='';sessionStorage.removeItem('nexus_portal_token');toast(e.message);S.token?render():login()}}
function shell(body){app.innerHTML=`<div class="shell"><div class="top"><div class="brand"><div class="mark">N</div><div><h1>NEXUS Control Center</h1><small>${esc(S.me?.display_name||S.me?.username||'Admin')}</small></div></div><div class="nav"><button data-p="dashboard">داشبورد</button><button data-p="users">کاربران</button><button data-p="signals">سیگنال‌ها</button><button data-p="risk">ریسک</button><button id="portalBtn">پرتال کاربر</button><button id="logout">خروج</button></div></div><div id="content">${body}</div></div>`;document.querySelectorAll('[data-p]').forEach(b=>{if(b.dataset.p===S.page)b.classList.add('active');b.onclick=()=>{S.page=b.dataset.p;render()}});$('#logout').onclick=()=>{localStorage.removeItem('nexus_admin_token');S.token='';login()};$('#portalBtn').onclick=portalLogin}
async function dashboard(){const d=await req('/dashboard');const c=await req('/capabilities');shell(`<div class="section-title"><h2>داشبورد</h2>${badge(d.global_kill_switch?'KILL SWITCH ON':'NORMAL')}</div><div class="grid"><section class="card metric"><b>${esc(d.stats.users)}</b><span>کاربر</span></section><section class="card metric"><b>${esc(d.entitlements.vip)}</b><span>VIP</span></section><section class="card metric"><b>${esc(d.entitlements.autotrade)}</b><span>AutoTrade</span></section><section class="card metric"><b>${esc(d.mt5_online)}</b><span>MT5 Online</span></section></div><section class="card"><h3>معماری اجرایی</h3><div class="row"><span>Signal Authority</span><b>${esc(c.signal_authorities.join(' / '))}</b></div><div class="row"><span>Mini App Signal Issuance</span>${badge(c.miniapp_signal_issuance)}</div><div class="row"><span>Risk Source</span><b>${esc(c.risk_source)}</b></div><div class="row"><span>MT5 Chart Capture</span>${badge(c.web_signal_chart_capture?'READY':'PENDING')}</div></section>`)}
async function users(){const d=await req('/users?limit=150');shell(`<div class="section-title"><h2>کاربران</h2><span>${d.items.length} مورد</span></div><section class="card table"><table><thead><tr><th>ID</th><th>نام</th><th>VIP</th><th>AutoTrade</th><th>امتیاز</th><th>انقضا</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc(x.telegram_id)}</td><td>${esc(x.first_name||x.username||'—')}</td><td>${badge(x.vip)}</td><td>${badge(x.autotrade)}</td><td>${esc(x.points_balance)}</td><td>${esc(x.license_expires_at||'—')}</td></tr>`).join('')}</tbody></table></section>`)}
async function signals(){const d=await req('/signals?limit=150');const o=await req('/signals/options');shell(`<div class="section-title"><h2>سیگنال‌ها</h2><span>${d.items.length} مورد</span></div><section class="card"><h3>صدور از Web</h3><p>${o.chart_capture_ready?'Screenshot Agent آماده است. فرم صدور در مرحله بعد فعال می‌شود.':'صدور وب تا اتصال کامل MT5 Screenshot Agent عمداً غیرفعال است تا Flashcard بدون چارت واقعی منتشر نشود.'}</p><button class="primary" disabled>ISSUE SIGNAL</button></section><section class="card table"><table><thead><tr><th>کد</th><th>نماد</th><th>جهت</th><th>TF</th><th>وضعیت</th><th>مقصد</th><th>Issuer</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.symbol)}</td><td>${esc(x.direction)}</td><td>${esc(x.timeframe)}</td><td>${badge(x.status)}</td><td>${esc(x.destination)}</td><td>${esc(x.issuer_type||'—')}</td></tr>`).join('')}</tbody></table></section>`)}
async function risk(){const d=await req('/risk/global');shell(`<div class="section-title"><h2>Risk Center</h2>${badge(d.kill_switch?'KILL SWITCH ON':'NORMAL')}</div><section class="card"><h3>Global Kill Switch</h3><p class="muted">این کنترل مستقیماً به Risk Firewall فعلی NEXUS متصل است و Source of Truth موازی ندارد.</p><button id="kill" class="${d.kill_switch?'danger':'primary'}">${d.kill_switch?'غیرفعال کردن Kill Switch':'فعال کردن Kill Switch'}</button></section>`);$('#kill').onclick=async()=>{if(!confirm(d.kill_switch?'Kill Switch غیرفعال شود؟':'تمام معاملات جدید متوقف شوند؟'))return;try{await req('/risk/global',{method:'PUT',body:JSON.stringify({enabled:!d.kill_switch})});toast('ذخیره شد');risk()}catch(e){toast(e.message)}}}
async function render(){if(!S.token)return login();try{S.me=S.me||await req('/auth/me');if(S.page==='users')return users();if(S.page==='signals')return signals();if(S.page==='risk')return risk();return dashboard()}catch(e){if(String(e.message).includes('نشست')||String(e.message).includes('401')){S.token='';localStorage.removeItem('nexus_admin_token');return login()}toast(e.message)}}
render();
